import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  const scenePos = config.scenePosition || new THREE.Vector3(0, 3, 0);
  const sceneRot = config.sceneRotation || new THREE.Euler(0, 0, 0);
  const sceneScale = config.sceneScale || new THREE.Vector3(1, 1, 1);

  group.position.copy(scenePos);
  group.rotation.copy(sceneRot);
  group.scale.copy(sceneScale);

  const timelines = [];
  const disposables = [];

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    disposables.forEach(item => {
      if (item && typeof item.dispose === 'function') {
        item.dispose();
      }
    });
  };

  group.userData.handlers = {};

  // Load and apply image texture
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png';
  const texture = ctx.textureLoader.load(imageUrl);
  disposables.push(texture);

  // Create background plane
  const planeGeom = new THREE.PlaneGeometry(1.6, 1.0);
  disposables.push(planeGeom);

  const planeMat = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
  });
  disposables.push(planeMat);

  const planeMesh = new THREE.Mesh(planeGeom, planeMat);
  planeMesh.position.z = 0;
  group.add(planeMesh);

  // Create text overlay
  const textContent = config.textContent || {};
  const textStr = textContent.text || 'Pricing';

  if (ctx.fontAtlas && ctx.fontAtlas.create) {
    const textMesh = ctx.fontAtlas.create({
      text: textStr,
      fontSize: 0.34,
      font: 'Lora-400',
      color: '#16161d',
    });

    if (textMesh) {
      textMesh.position.z = 0.1;
      group.add(textMesh);
    }
  }

  return group;
}
